<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {api} from '../api'
import {Ban,Landmark,RefreshCw,ShieldAlert,WalletCards} from 'lucide-vue-next'

const accounts=ref<any[]>([]),selected=ref(''),data=ref<any>(null),loading=ref(false),error=ref(''),notice=ref('')
const accountForm=ref({name:'A股策略模拟账户',initial_cash:1000000,max_order_value:100000,max_position_ratio:0.3})
const order=ref({symbol:'600000',side:'buy',quantity:100,snapshot_price:10,trade_date:new Date().toISOString().slice(0,10),source:'manual_replay'})
const account=computed(()=>data.value?.account)
async function loadAccounts(){accounts.value=(await api.get('/paper/accounts')).data;if(!selected.value&&accounts.value.length)selected.value=accounts.value[0].id;if(selected.value)await loadSnapshot()}
async function loadSnapshot(){loading.value=true;try{data.value=(await api.get(`/paper/accounts/${selected.value}`)).data}finally{loading.value=false}}
async function createAccount(){error.value='';try{const created=(await api.post('/paper/accounts',accountForm.value)).data;selected.value=created.id;await loadAccounts();notice.value='模拟账户已创建'}catch(e:any){error.value=e.response?.data?.detail||e.message}}
async function submitOrder(){error.value='';notice.value='';try{const result=(await api.post(`/paper/accounts/${selected.value}/orders`,order.value)).data;notice.value=result.status==='filled'?'模拟成交完成':`订单被风控拒绝：${result.message}`;await loadSnapshot()}catch(e:any){error.value=e.response?.data?.detail||e.message}}
async function settle(){error.value='';try{data.value=(await api.post(`/paper/accounts/${selected.value}/settle`,{trade_date:order.value.trade_date})).data;notice.value='交易日结算完成，历史买入持仓已更新为可卖'}catch(e:any){error.value=e.response?.data?.detail||e.message}}
async function freeze(){if(!confirm('确认冻结该模拟账户？冻结后不能继续下单。'))return;await api.post(`/paper/accounts/${selected.value}/freeze`);await loadSnapshot()}
onMounted(loadAccounts)
</script>

<template><section><div class="page-intro"><div><h2>模拟交易台</h2><p>完全隔离环境 · 不连接券商 · 不会产生真实订单</p></div><div class="paper-badge"><ShieldAlert :size="15"/>PAPER ONLY</div></div><p v-if="error" class="error-box">{{error}}</p><p v-if="notice" class="notice-box">{{notice}}</p><article v-if="!accounts.length" class="panel empty-account"><WalletCards :size="40"/><h3>创建第一个模拟账户</h3><p>使用虚拟资金验证策略、交易规则和风险限制。</p><div class="form-grid"><div class="field"><label>账户名称</label><input v-model="accountForm.name"/></div><div class="field"><label>初始虚拟资金</label><input v-model.number="accountForm.initial_cash" type="number"/></div><div class="field"><label>单笔金额上限</label><input v-model.number="accountForm.max_order_value" type="number"/></div><div class="field"><label>单票仓位上限</label><input v-model.number="accountForm.max_position_ratio" type="number" step="0.05"/></div></div><button class="primary" @click="createAccount">创建模拟账户</button></article><template v-else><div class="paper-toolbar"><select v-model="selected" @change="loadSnapshot"><option v-for="item in accounts" :key="item.id" :value="item.id">{{item.name}}</option></select><button class="secondary" @click="loadSnapshot"><RefreshCw :size="15" :class="{spin:loading}"/>刷新</button><button class="secondary danger-outline" @click="freeze"><Ban :size="15"/>紧急冻结</button></div><div v-if="data" class="paper-metrics"><article><small>总资产</small><strong>¥{{Number(data.equity).toLocaleString()}}</strong></article><article><small>可用资金</small><strong>¥{{Number(account.cash).toLocaleString()}}</strong></article><article><small>持仓市值</small><strong>¥{{Number(data.market_value).toLocaleString()}}</strong></article><article><small>累计盈亏</small><strong :class="Number(data.total_profit)>=0?'gain':'loss'">¥{{Number(data.total_profit).toLocaleString()}}</strong></article><article><small>账户状态</small><i class="status" :class="account.status">{{account.status}}</i></article></div><div v-if="data" class="paper-grid"><article class="panel order-ticket"><div class="panel-head"><div><h3>模拟下单</h3><p>价格来自手工/历史回放快照</p></div><Landmark :size="19"/></div><div class="field"><label>证券代码</label><input v-model="order.symbol" maxlength="6"/></div><div class="side-switch"><button :class="{selected:order.side==='buy'}" @click="order.side='buy'">买入</button><button :class="{selected:order.side==='sell'}" @click="order.side='sell'">卖出</button></div><div class="form-grid"><div class="field"><label>数量（整手）</label><input v-model.number="order.quantity" type="number" step="100" min="100"/></div><div class="field"><label>回放价格</label><input v-model.number="order.snapshot_price" type="number" step="0.01" min="0.01"/></div></div><div class="field"><label>模拟交易日</label><input v-model="order.trade_date" type="date"/></div><button class="primary submit-order" :disabled="account.status!=='active'" @click="submitOrder">提交模拟订单</button><button class="secondary settle-button" @click="settle">推进至该交易日并结算 T+1</button><p class="simulation-warning">该价格不是实时行情，仅用于验证订单、资金和风控流程。</p></article><div class="paper-records"><article class="panel"><div class="panel-head"><div><h3>当前持仓</h3><p>买入当日数量不会进入可卖持仓</p></div></div><div class="mini-row mini-head"><span>代码</span><span>数量/可卖</span><span>成本</span><span>最新价</span></div><div class="mini-row" v-for="position in data.positions" :key="position.id"><b>{{position.symbol}}</b><span>{{position.quantity}} / {{position.sellable_quantity}}</span><span>{{position.average_cost}}</span><span>{{position.last_price}}</span></div><div v-if="!data.positions.length" class="empty">暂无持仓</div></article><article class="panel"><div class="panel-head"><div><h3>最近订单</h3><p>成交和风控拒绝都会永久留痕</p></div></div><div class="mini-row order-history mini-head"><span>日期</span><span>代码</span><span>方向</span><span>数量</span><span>状态</span></div><div class="mini-row order-history" v-for="item in data.orders.slice(0,8)" :key="item.id"><span>{{item.trade_date}}</span><b>{{item.symbol}}</b><span>{{item.side}}</span><span>{{item.quantity}}</span><i class="status" :class="item.status">{{item.status}}</i></div><div v-if="!data.orders.length" class="empty">暂无订单</div></article></div></div></template></section></template>
